INSERT INTO public.loan_reminder_email_variants
  (subject, preview_text, body_html, category, active, weight, sequence_index, day_index, slot, phase, seed_tag)
VALUES
  ('Twoja nieruchomość może dać Ci gotówkę', 'Sprawdź, ile możesz dostać pod zastaw mieszkania lub domu.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, Twoja nieruchomość to nie tylko cztery ściany — to realna gotówka w Twoim zasięgu.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Wystarczy mieszkanie, dom, działka albo lokal, żeby uruchomić pożyczkę bez zbędnych formalności.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Sprawdź ofertę w kalkulatorze →</a></p>', 'followup', true, 1, 1, 1, 'morning', 'P1', 'followup_v2_2026'),
  ('Bez BIK, bez ZUS, bez zaświadczeń', 'Zabezpieczeniem jest nieruchomość, więc papiery odpadają.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, u nas nie pytamy o BIK, ZUS ani zaświadczenia o zarobkach.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Zabezpieczeniem jest Twoja nieruchomość, dlatego cała reszta papierologii po prostu odpada.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 2, 1, 'evening', 'P1', 'followup_v2_2026'),
  ('Decyzja wstępna już w 24 godziny', 'Nie musisz czekać tygodniami — wstępną decyzję masz w dobę.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, wiemy, że czas ma znaczenie, dlatego decyzję wstępną dostajesz w 24 godziny.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Zacznij dziś, a jutro możesz wiedzieć, na czym stoisz.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 3, 2, 'morning', 'P1', 'followup_v2_2026'),
  ('Ponad 300 inwestorów czeka na Twój wniosek', 'To oni konkurują o Ciebie — Ty wybierasz najlepszą ofertę.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, u nas to inwestorzy walczą o Twój wniosek, a nie odwrotnie.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Ponad 300 aktywnych inwestorów rywalizuje o możliwość sfinansowania Twojej pożyczki — a najkorzystniejszą ofertę wybierasz Ty.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Zobacz swoją ofertę →</a></p>', 'followup', true, 1, 4, 2, 'evening', 'P1', 'followup_v2_2026'),
  ('Niska rata nawet na 70 miesięcy', 'Rozłóż spłatę wygodnie i oddychaj spokojnie każdego miesiąca.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, spłatę możesz rozłożyć nawet na 70 miesięcy.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Dłuższy okres to niższa, realna rata, która nie rujnuje domowego budżetu.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Policz swoją ratę →</a></p>', 'followup', true, 1, 5, 3, 'morning', 'P1', 'followup_v2_2026'),
  ('Twoje mieszkanie zostaje Twoje', 'Dostajesz gotówkę, a nieruchomość cały czas jest Twoją własnością.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, przy naszej pożyczce nieruchomość przez cały czas pozostaje Twoją własnością.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Otrzymujesz gotówkę, a dalej mieszkasz i korzystasz ze swojego mieszkania jak dotychczas.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 6, 3, 'evening', 'P1', 'followup_v2_2026'),
  ('Wypłata średnio w 10 dni', 'Od wniosku do pieniędzy na koncie zwykle mija 7–14 dni.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, od złożenia wniosku do wypłaty mija zwykle 7–14 dni, średnio około dziesięciu.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Do notariusza jedziesz tylko raz, resztę załatwiamy online.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 7, 4, 'morning', 'P1', 'followup_v2_2026'),
  ('Policz swoją ratę w 2 minuty', 'Kalkulator pokaże Ci konkretną kwotę bez żadnych zobowiązań.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, zanim cokolwiek zdecydujesz, sprawdź konkretne liczby.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Nasz kalkulator w dwie minuty pokaże Ci wysokość raty — bez zobowiązań i bez zbędnych pytań.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Sprawdź ofertę w kalkulatorze →</a></p>', 'followup', true, 1, 8, 4, 'evening', 'P1', 'followup_v2_2026'),
  ('Też z obciążeniami? Też się liczy', 'Nieruchomość z hipoteką albo obciążeniami wciąż może być zabezpieczeniem.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, nawet nieruchomość z obciążeniami czy hipoteką może być zabezpieczeniem pożyczki.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Nie skreślaj się z góry — sprawdźmy razem, co da się zrobić w Twojej sytuacji.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 9, 5, 'morning', 'P1', 'followup_v2_2026'),
  ('Od 30 tys. do kilku milionów zł', 'Niezależnie od skali potrzeby — mamy dla Ciebie rozwiązanie.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, finansujemy kwoty od około 30 tysięcy aż do kilku milionów złotych.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Niezależnie od tego, ile potrzebujesz, znajdziemy odpowiednie rozwiązanie.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Sprawdź ofertę w kalkulatorze →</a></p>', 'followup', true, 1, 10, 5, 'evening', 'P1', 'followup_v2_2026'),
  ('Wycenę robimy my — nie Ty', 'Żadnego operatu szacunkowego z Twojej strony.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, nie musisz zamawiać ani opłacać operatu szacunkowego.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Wycenę nieruchomości bierzemy na siebie — Ty tylko składasz wniosek.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 11, 6, 'morning', 'P1', 'followup_v2_2026'),
  ('Twój wniosek jest niedokończony', 'Zostało dosłownie kilka pól — szkoda, żeby oferta przepadła.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, Twój wniosek jest już prawie gotowy, brakuje dosłownie kilku informacji.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Dokończ go teraz, a inwestorzy będą mogli przygotować dla Ciebie oferty.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Dokończ wniosek →</a></p>', 'followup', true, 1, 12, 6, 'evening', 'P1', 'followup_v2_2026'),
  ('Wszystko online, do notariusza raz', 'Cała procedura zdalnie — u notariusza pojawiasz się jeden raz.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, całą procedurę przechodzisz online, z domu.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Do notariusza jedziesz tylko raz, żeby podpisać — nic więcej Cię nie czeka.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 13, 7, 'morning', 'P1', 'followup_v2_2026'),
  ('Poznaj Anię, swojego opiekuna', 'Jedna osoba prowadzi Cię przez cały proces od A do Z.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, przez cały proces prowadzi Cię jedna osoba — Twoja opiekunka Ania.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Zawsze wiesz, do kogo napisać i na jakim etapie jesteś.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 14, 7, 'evening', 'P1', 'followup_v2_2026'),
  ('Zero drobnego druku', 'Musisz rozumieć każdy zapis umowy — pilnujemy tego.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, u nas nie ma drobnego druku ani ukrytych zapisów.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Zależy nam, żebyś rozumiał każdy punkt umowy, zanim cokolwiek podpiszesz.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 15, 8, 'morning', 'P1', 'followup_v2_2026'),
  ('Sprawdź ofertę, zanim zdecydujesz', 'Zobaczenie liczb do niczego Cię nie zobowiązuje.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, sprawdzenie oferty nie oznacza żadnego zobowiązania.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Zobacz konkretne liczby i dopiero potem spokojnie zdecyduj, co dalej.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Zobacz swoją ofertę →</a></p>', 'followup', true, 1, 16, 8, 'evening', 'P1', 'followup_v2_2026'),
  ('Gotówka na to, co ważne teraz', 'Remont, konsolidacja, firma czy plany rodzinne — Ty decydujesz.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, środki z pożyczki możesz przeznaczyć na cokolwiek potrzebujesz.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Remont, spłata długów, rozwój firmy czy plany rodzinne — cel wybierasz sam.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 17, 9, 'morning', 'P1', 'followup_v2_2026'),
  ('Prościej, niż myślisz', 'Bez stert dokumentów i bez chodzenia po urzędach.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, cały proces jest prostszy, niż zwykle się wydaje.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Bez stert dokumentów, bez biegania po urzędach — wystarczy nieruchomość i chwila czasu.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Sprawdź ofertę w kalkulatorze →</a></p>', 'followup', true, 1, 18, 9, 'evening', 'P1', 'followup_v2_2026'),
  ('Twoja oferta wciąż czeka', 'Zaczęty wniosek nie przepadł — możesz wrócić w każdej chwili.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, Twój rozpoczęty wniosek wciąż na Ciebie czeka.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Możesz wrócić do niego w każdej chwili i dokończyć w kilka minut.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Dokończ wniosek →</a></p>', 'followup', true, 1, 19, 10, 'morning', 'P1', 'followup_v2_2026'),
  ('Ile realnie możesz pożyczyć?', 'Wpisz wartość nieruchomości i zobacz konkretną kwotę.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, chcesz wiedzieć, ile realnie możesz pożyczyć pod zastaw swojej nieruchomości?</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Wpisz jej wartość w kalkulatorze i zobacz konkretną kwotę oraz ratę.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Policz swoją ratę →</a></p>', 'followup', true, 1, 20, 10, 'evening', 'P1', 'followup_v2_2026'),
  ('Pani Anna z Krakowa dostała 240 tys.', 'Bez zaświadczeń, pod zastaw mieszkania, w 11 dni.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, pani Anna z Krakowa potrzebowała gotówki na spłatę zobowiązań.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Pod zastaw mieszkania dostała 240 tysięcy złotych w jedenaście dni — bez BIK i bez zaświadczeń.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 21, 11, 'morning', 'P1', 'followup_v2_2026'),
  ('Pan Marek z Wrocławia: rata o połowę niższa', 'Konsolidacja kilku długów w jedną wygodną ratę.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, pan Marek z Wrocławia miał kilka rat w różnych miejscach.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Skonsolidował je w jedną pożyczkę na 70 miesięcy i jego miesięczna rata spadła niemal o połowę.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Policz swoją ratę →</a></p>', 'followup', true, 1, 22, 11, 'evening', 'P1', 'followup_v2_2026'),
  ('Jak Kasia z Gdańska uratowała firmę', 'Gotówka pod zastaw lokalu w niecałe dwa tygodnie.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, Kasia z Gdańska potrzebowała szybkiego zastrzyku gotówki dla firmy.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Pod zastaw lokalu dostała środki w niecałe dwa tygodnie i utrzymała płynność.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 23, 12, 'morning', 'P1', 'followup_v2_2026'),
  ('300 inwestorów, jedna Twoja wygrana', 'Konkurencja o wniosek działa na Twoją korzyść.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, kiedy ponad 300 inwestorów konkuruje o jeden wniosek, wygrywa klient.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">To Ty wybierasz najkorzystniejszą ofertę spośród tych, które dla Ciebie przygotują.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Zobacz swoją ofertę →</a></p>', 'followup', true, 1, 24, 12, 'evening', 'P1', 'followup_v2_2026'),
  ('Realna rata, nie obietnica z reklamy', 'Kalkulator liczy konkretne liczby dla Twojej kwoty.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, u nas rata to nie hasło z reklamy, tylko konkretna liczba.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Sprawdź w kalkulatorze, ile dokładnie zapłacisz przy rozłożeniu na 70 miesięcy.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Sprawdź ofertę w kalkulatorze →</a></p>', 'followup', true, 1, 25, 13, 'morning', 'P1', 'followup_v2_2026'),
  ('Pan Tomasz z Poznania: 500 tys. na rozwój', 'Pod zastaw magazynu, bez PIT-ów i operatu.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, pan Tomasz z Poznania chciał rozwinąć działalność.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Pod zastaw magazynu pozyskał 500 tysięcy złotych — bez PIT-ów i bez operatu szacunkowego.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 26, 13, 'evening', 'P1', 'followup_v2_2026'),
