  ('Odetchnij od nawału zobowiązań', 'Jedna pożyczka zamiast kilku napiętych rat.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, jeśli kilka rat spina Twój budżet do granic, jest wyjście.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Połącz zobowiązania w jedno i oddychaj spokojniej każdego miesiąca.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Policz swoją ratę →</a></p>', 'followup', true, 1, 48, 24, 'evening', 'P1', 'followup_v2_2026'),
