  ('Wróć, gdy tylko zechcesz', 'Twój wniosek czeka, a oferta wciąż otwarta.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, drzwi wciąż są otwarte, a Twój wniosek zapisany.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Wróć w dowolnym momencie i dokończ go bez pośpiechu.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Dokończ wniosek →</a></p>', 'followup', true, 1, 76, 62, 'morning', 'P2', 'followup_v2_2026'),
