  ('Twoja oferta na {{loan_amount}} czeka', 'Sprawdź warunki dopasowane do Twojej kwoty.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, przygotujemy dla Ciebie warunki na kwotę {{loan_amount}}.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Sprawdź, jak wygląda oferta i jaka wyjdzie rata.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Zobacz swoją ofertę →</a></p>', 'followup', true, 1, 78, 66, 'morning', 'P2', 'followup_v2_2026'),
  ('Prosto, jasno, po ludzku', 'Bez żargonu i bez ukrytych haczyków.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, tłumaczymy wszystko prosto i po ludzku.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Bez żargonu, bez haczyków — po to, żebyś czuł się pewnie na każdym etapie.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 79, 68, 'morning', 'P2', 'followup_v2_2026'),
  ('Decyzja w dobę, spokój na dłużej', 'Szybka odpowiedź i wygodna spłata na lata.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, wstępną decyzję dostajesz w 24 godziny.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">A dzięki okresowi do 70 miesięcy zyskujesz spokój na dłużej.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 80, 70, 'morning', 'P2', 'followup_v2_2026'),
  ('Twoje cztery ściany, Twój kapitał', 'Zamień wartość nieruchomości w realną gotówkę.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, w Twoich czterech ścianach drzemie realny kapitał.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Zamień go w gotówkę, nie tracąc prawa do własnego mieszkania.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Sprawdź ofertę w kalkulatorze →</a></p>', 'followup', true, 1, 81, 72, 'morning', 'P2', 'followup_v2_2026'),
  ('Konsolidacja, która realnie odciąża', 'Jedna rata zamiast wielu — policz różnicę.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, wiele rat potrafi dusić budżet co miesiąca.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Połącz je w jedną pożyczkę na 70 miesięcy i policz, ile zyskasz.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Policz swoją ratę →</a></p>', 'followup', true, 1, 82, 74, 'morning', 'P2', 'followup_v2_2026'),
