  ('Twoja oferta wciąż czeka na dokończenie', 'Kilka pól dzieli Cię od propozycji inwestorów.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, brakuje naprawdę niewiele, żeby ruszyć z ofertami.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Dokończ wniosek i pozwól inwestorom przygotować dla Ciebie propozycje.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Dokończ wniosek →</a></p>', 'followup', true, 1, 98, 106, 'morning', 'P2', 'followup_v2_2026'),
  ('Spokojna spłata, jasne warunki', 'Wygodna rata i pełna transparentność w jednym.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, łączymy wygodną, niską ratę z pełną jasnością warunków.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Wiesz, ile spłacasz i na jakich zasadach — od pierwszego do ostatniego miesiąca.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 99, 108, 'morning', 'P2', 'followup_v2_2026'),
  ('Zamień zastój w działanie', 'Gotówka pod zastaw ruszy Twoje plany z miejsca.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, jeśli brak środków blokuje Twoje plany, jest rozwiązanie.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Gotówka pod zastaw nieruchomości ruszy je z miejsca w kilkanaście dni.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 100, 110, 'morning', 'P2', 'followup_v2_2026'),
  ('Drzwi wciąż otwarte', 'Nie zamykamy Twojego wniosku — wracaj śmiało.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, kiedy tylko będziesz gotowy, wracaj do swojego wniosku.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Jest zapisany i czeka — bez pośpiechu i bez presji.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Dokończ wniosek →</a></p>', 'followup', true, 1, 101, 112, 'morning', 'P2', 'followup_v2_2026'),
  ('Pani Dorota z Torunia poleca spokój', 'Gotówka pod zastaw mieszkania i żadnych kolejek.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, pani Dorota z Torunia bała się formalności, a okazało się prościej.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Gotówkę pod zastaw mieszkania dostała bez kolejek i bez zaświadczeń.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 102, 114, 'morning', 'P2', 'followup_v2_2026'),
  ('Policz ratę raz jeszcze', 'Może dziś liczby ułożą się lepiej, niż sądzisz.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, jeśli wcześniej wahałeś się przez ratę, policz ją jeszcze raz.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Przy okresie do 70 miesięcy może wyjść wygodniej, niż zakładałeś.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Policz swoją ratę →</a></p>', 'followup', true, 1, 103, 116, 'morning', 'P2', 'followup_v2_2026'),
  ('Twoja gotówka wciąż w zasięgu', 'Wniosek gotowy do dokończenia w kilka minut.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, potrzebna gotówka wciąż jest w Twoim zasięgu.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Wystarczy dokończyć wniosek — reszta dzieje się po naszej stronie.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Dokończ wniosek →</a></p>', 'followup', true, 1, 104, 118, 'morning', 'P2', 'followup_v2_2026'),
  ('Bez papierów, bez nerwów', 'Zabezpieczeniem jest nieruchomość — reszta odpada.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, mniej papierów to mniej nerwów.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Zabezpieczeniem jest nieruchomość, więc zaświadczenia i operat po prostu odpadają.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 105, 120, 'morning', 'P2', 'followup_v2_2026'),
  ('Sprawdź ofertę, zanim zdecydujesz cokolwiek', 'Poznanie liczb do niczego Cię nie zobowiązuje.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, warto poznać konkretną ofertę, zanim cokolwiek postanowisz.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Sprawdzenie liczb jest darmowe i niezobowiązujące.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Zobacz swoją ofertę →</a></p>', 'followup', true, 1, 106, 122, 'morning', 'P2', 'followup_v2_2026'),
  ('Twój dom pracuje, Ty odpoczywasz', 'Kapitał uwolniony, własność cały czas Twoja.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, pozwól, żeby Twoja nieruchomość pracowała dla Ciebie.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Uwalniasz kapitał, zostajesz właścicielem i nadal mieszkasz u siebie.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 107, 124, 'morning', 'P2', 'followup_v2_2026'),
  ('Konsolidacja z jasnymi zasadami', 'Jedna rata, zero drobnego druku.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, połącz zobowiązania w jedną wygodną ratę.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Wszystko jasno, bez drobnego druku i bez ukrytych kosztów.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Policz swoją ratę →</a></p>', 'followup', true, 1, 108, 126, 'morning', 'P2', 'followup_v2_2026'),
  ('Ostatni moment, by ruszyć bez zwłoki', 'Im szybciej zaczniesz, tym szybciej masz gotówkę.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, jeśli odkładasz decyzję, tracisz tylko czas.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Zacznij dziś — wstępna decyzja w 24 godziny, wypłata w około 10 dni.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 109, 128, 'morning', 'P2', 'followup_v2_2026'),
  ('Pan Krzysztof z Opola: firma uratowana', 'Szybka gotówka pod zastaw magazynu w 13 dni.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, pan Krzysztof z Opola potrzebował gotówki na już.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Pod zastaw magazynu dostał środki w 13 dni i utrzymał firmę na powierzchni.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 110, 130, 'morning', 'P2', 'followup_v2_2026'),
  ('Twoje pytania mają odpowiedzi', 'Ania rozwieje każdą wątpliwość bez presji.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, każda Twoja wątpliwość ma u nas odpowiedź.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Napisz do Ani — spokojnie i po ludzku wyjaśni to, co niejasne.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 111, 132, 'morning', 'P2', 'followup_v2_2026'),
  ('Zobacz swoją ratę na {{loan_amount}}', 'Konkretna liczba dla Twojej kwoty w 2 minuty.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, chcesz wiedzieć, jaka rata wyjdzie przy {{loan_amount}}?</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Wpisz kwotę w kalkulatorze i zobacz konkretny wynik w dwie minuty.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Policz swoją ratę →</a></p>', 'followup', true, 1, 112, 134, 'morning', 'P2', 'followup_v2_2026'),
  ('Nieruchomość zostaje Twoja — obiecujemy', 'Gotówka teraz, własność cały czas przy Tobie.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, przy naszej pożyczce nie tracisz nieruchomości.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Dostajesz gotówkę, a dom czy mieszkanie przez cały czas należą do Ciebie.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 113, 136, 'morning', 'P2', 'followup_v2_2026'),
  ('Jeszcze tu jesteśmy dla Ciebie', 'Twój wniosek czeka, a my gotowi pomóc.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, wciąż jesteśmy tu, żeby Ci pomóc.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Twój wniosek jest zapisany — wróć do niego, kiedy będziesz gotowy.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Dokończ wniosek →</a></p>', 'followup', true, 1, 114, 138, 'morning', 'P2', 'followup_v2_2026'),
  ('Mniej stresu, więcej możliwości', 'Prosty proces i wygodna spłata na lata.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, gotówka pod zastaw to mniej stresu i więcej możliwości.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Prosty proces, szybka decyzja i wygodna rata rozłożona nawet na 70 miesięcy.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 115, 140, 'morning', 'P2', 'followup_v2_2026'),
  ('Sprawdź, ile realnie zapłacisz', 'Bez domysłów — kalkulator pokaże konkret.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, zamiast się domyślać, sprawdź konkretny koszt.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Kalkulator pokaże Ci realną ratę dopasowaną do Twojej kwoty i okresu.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Sprawdź ofertę w kalkulatorze →</a></p>', 'followup', true, 1, 116, 142, 'morning', 'P2', 'followup_v2_2026'),
  ('Twoja decyzja, Twoje tempo', 'Bez presji — my tylko pokazujemy możliwości.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, decyzję podejmujesz w swoim tempie i na swoich zasadach.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">My jedynie pokazujemy możliwości i konkretne liczby — reszta należy do Ciebie.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Zobacz swoją ofertę →</a></p>', 'followup', true, 1, 117, 144, 'morning', 'P2', 'followup_v2_2026'),
  ('300+ inwestorów wciąż czeka', 'Twój dokończony wniosek uruchamia ich oferty.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, ponad 300 inwestorów wciąż jest gotowych zawalczyć o Twój wniosek.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Wystarczy, że go dokończysz, a ruszy konkurencja o najlepszą ofertę.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Dokończ wniosek →</a></p>', 'followup', true, 1, 118, 146, 'morning', 'P2', 'followup_v2_2026'),
  ('Zacznij dziś, odetchnij jutro', 'Decyzja w dobę, spokój na wiele miesięcy.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, jeden krok dziś potrafi zmienić Twoje jutro.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Decyzja wstępna w 24 godziny, a potem wygodna spłata na Twoich warunkach.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Uzupełnij wniosek teraz →</a></p>', 'followup', true, 1, 119, 148, 'morning', 'P2', 'followup_v2_2026'),
  ('Twoja oferta jest o krok od Ciebie', 'Dokończ wniosek i zobacz, co przygotowali inwestorzy.', '<p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">{{greeting}}, jesteś dosłownie o krok od zobaczenia swojej oferty.</p><p style="margin:0 0 14px;font-size:15px;line-height:1.7;color:#0f172a">Dokończ wniosek, a ponad 300 inwestorów przygotuje dla Ciebie propozycje.</p><p style="text-align:center;margin:24px 0 6px"><a href="{{link}}" style="display:inline-block;background:#0a7f4f;color:#ffffff;font-weight:700;font-size:16px;line-height:1;padding:15px 30px;border-radius:9999px;text-decoration:none">Zobacz swoją ofertę →</a></p>', 'followup', true, 1, 120, 150, 'morning', 'P2', 'followup_v2_2026');
